(73, 'T1', 'Status pekerjaan atau aktivitas Anda saat ini:', 'Sesuai klasifikasi Tracer Study Universitas Ma Chung.', 'pilihan_ganda', 'kompetensi', 'alumni', NULL, 1, NULL, NULL, NULL, NULL, 11, 1, 1, '2026-10-07 10:00:00', 0, 0),
(74, 'T2', 'Berapa lama waktu tunggu Anda hingga mendapatkan pekerjaan pertama setelah lulus?', 'Pilih "Belum bekerja / tidak melamar" bila belum bekerja.', 'pilihan_ganda', 'kompetensi', 'alumni', NULL, 1, NULL, NULL, NULL, NULL, 12, 1, 1, '2026-10-07 10:00:00', 0, 0),
(75, 'T3', 'Apakah bidang pekerjaan Anda saat ini sesuai dengan latar belakang pendidikan Sistem Informasi?', 'Membantu prodi memetakan keselarasan kurikulum dengan bidang kerja alumni.', 'pilihan_ganda', 'kompetensi', 'alumni', NULL, 1, NULL, NULL, NULL, NULL, 13, 1, 1, '2026-10-07 10:00:00', 0, 0),
(76, 'T4', 'Apa level atau skala perusahaan / usaha tempat Anda bekerja saat ini?', 'Sesuai kategori Tracer Study 2024.', 'pilihan_ganda', 'kompetensi', 'alumni', NULL, 1, NULL, NULL, NULL, NULL, 14, 1, 1, '2026-10-07 10:00:00', 0, 0),
(77, 'T5', 'Bagaimana tingkat penghasilan/gaji bulanan Anda dibandingkan UMP setempat?', 'Bersifat rahasia dan hanya digunakan untuk pemetaan indikator kinerja lulusan.', 'pilihan_ganda', 'kompetensi', 'alumni', NULL, 0, NULL, NULL, NULL, NULL, 15, 1, 1, '2026-10-07 10:00:00', 0, 0),
(78, 'T1', 'Apa skala atau level perusahaan Anda saat ini?', 'Digunakan untuk memetakan kebutuhan kurikulum berdasarkan skala industri.', 'pilihan_ganda', 'kompetensi', 'perusahaan', NULL, 1, NULL, NULL, NULL, NULL, 11, 1, 1, '2026-10-07 10:00:00', 0, 0),
(79, 'T2', 'Bidang posisi apa yang paling sering perusahaan Anda buka untuk lulusan Sistem Informasi / TI?', 'Pilih paling banyak 3 posisi yang paling dibutuhkan (mengacu sebaran lowongan DUDI).', 'pilihan_ganda_banyak', 'kompetensi', 'perusahaan', NULL, 1, NULL, NULL, NULL, 3, 12, 1, 1, '2026-10-07 10:00:00', 0, 0);

