INSERT INTO `tiket` (`id`, `pengguna_id`, `subjek`, `isi`, `status`, `balasan_admin`, `dibuat_pada`, `diperbarui_pada`) VALUES
(1, 10, 'Pembaruan Nama Instansi & Posisi Kerja', 'Halo Admin, saya baru pindah posisi sebagai Fullstack Developer di PT Teknologi Maju. Mohon info apakah data profil alumni sudah otomatis tersinkronisasi?', 'selesai', 'Halo Andi, terima kasih informasinya. Data profil Anda sudah dapat diperbarui langsung melalui menu Profil dan sudah kami verifikasi.', '2026-10-02 09:15:00', '2026-10-02 11:20:00'),
(2, 5, 'Kendala Memilih Mata Kuliah Pilihan Semester 7', 'Selamat siang Admin, saya belum mengambil mata kuliah pilihan semester 7. Apakah saat evaluasi wajib memilih mata kuliah pilihan juga?', 'selesai', 'Halo Marcell, cukup pilih mata kuliah yang sudah pernah Anda tempuh saja. Minimal 1 mata kuliah untuk dapat melanjutkan ke bagian kompetensi.', '2026-10-03 13:40:00', '2026-10-03 14:10:00'),
(3, 46, 'Permintaan Ringkasan Kurikulum Terbaru 2024', 'Selamat pagi, dari tim IT Talent PT Astra International ingin menanyakan apakah tersedia deskripsi singkat silabus untuk mata kuliah Enterprise System dan SCM.', 'diproses', 'Terima kasih atas atensinya. Tim prodi sedang menyiapkan dokumen ringkasan RPS Kurikulum 2024 untuk dikirimkan melalui email resmi perusahaan.', '2026-10-04 08:30:00', '2026-10-05 09:05:00'),
(4, 43, 'Informasi Program Sertifikasi & Karir Alumni', 'Halo Admin Prodi SI, sebagai lulusan 2023 yang sedang mencari kerja, apakah ada rekomendasi pelatihan atau bursa kerja dari mitra prodi?', 'baru', NULL, '2026-10-05 10:12:00', '2026-10-05 10:12:00'),
(5, 2, 'Konfirmasi Simpan Draf Otomatis', 'Permisi admin, saat saya mengisi formulir lalu pindah tab, apakah jawaban mata kuliah yang sudah saya pilih otomatis tersimpan?', 'selesai', 'Betul Carlo, sistem menyimpan draf otomatis setiap ada perubahan jawaban maupun saat berpindah tab.', '2026-10-06 08:20:00', '2026-10-06 09:00:00'),
(6, 6, 'Usulan Penambahan Bahan Kajian Cloud Computing', 'Yth. Admin Prodi, apakah bahan kajian baru untuk Cloud Computing & DevOps sudah dapat ditambahkan sebelum periode ditutup?', 'diproses', 'Terima kasih Pak Daniel. Usulan sudah dicatat untuk rapat peninjauan kurikulum bersama Kaprodi minggu ini.', '2026-10-07 10:45:00', '2026-10-08 08:15:00'),
(7, 15, 'Akses Akun Tambahan untuk Tim Hiring Manager', 'Halo tim SI Ma Chung, kami dari Tokopedia ingin mendaftarkan 1 akun tambahan untuk Engineering Manager agar ikut memberi masukan kurikulum.', 'selesai', 'Terima kasih Tokopedia. Silakan kirimkan nama dan email perwakilan terkait agar kami daftarkan melalui Master Perusahaan.', '2026-10-08 11:00:00', '2026-10-08 15:30:00'),
(8, 28, 'Pertanyaan Tentang Status Pekerjaan Tracer Study', 'Halo admin, jika saya bekerja fulltime di perusahaan multinasional sekaligus freelance proyek, opsi status pekerjaan mana yang paling tepat?', 'selesai', 'Halo Bryan, silakan pilih "Bekerja (Fulltime / Parttime)" sesuai pekerjaan utama Anda saat ini.', '2026-10-09 14:15:00', '2026-10-09 16:00:00'),
(9, 18, 'Lupa Kata Sandi Akun Mahasiswa', 'Halo admin, teman saya kesulitan login karena lupa kata sandi setelah mengganti password awal. Bagaimana prosedur resetnya?', 'selesai', 'Silakan gunakan fitur Lupa Kata Sandi di halaman login atau hubungi admin prodi dengan menyertakan NIM.', '2026-10-10 09:50:00', '2026-10-10 10:25:00'),
(10, 47, 'Kolaborasi Kuliah Tamu Business Analytics', 'Tim Campus Hiring Deloitte Indonesia tertarik mengadakan sesi kuliah tamu mengenai Business Analysis & ERP untuk mahasiswa semester 5-7.', 'diproses', 'Sangat menyambut baik! Tim prodi akan menghubungi kembali melalui email resmi untuk penjadwalan semester berjalan.', '2026-10-11 13:10:00', '2026-10-12 09:00:00'),
(11, 29, 'Perubahan Alamat Email Alumni', 'Selamat pagi admin, saya ingin mengganti email akun alumni saya ke email pribadi terbaru agar notifikasi evaluasi selanjutnya tetap masuk.', 'selesai', 'Halo Evelyn, pembaruan email dapat dilakukan melalui Admin Master Alumni. Mohon informasikan alamat email baru Anda.', '2026-10-12 08:40:00', '2026-10-12 10:05:00'),
(12, 7, 'Sinkronisasi Bobot SKS Enterprise System', 'Di daftar mata kuliah tertera Enterprise System 5 SKS. Mohon konfirmasi apakah sudah termasuk praktikum SAP/Odoo?', 'selesai', 'Benar Pak Budi, bobot 5 SKS sudah mencakup sesi teori dan praktikum terintegrasi sesuai Kurikulum 2024.', '2026-10-13 15:20:00', '2026-10-13 16:45:00'),
(13, 35, 'Masukan Portofolio UI/UX untuk Mahasiswa', 'Halo admin, sebagai alumni UI/UX di Tokopedia, apakah ada wadah bagi alumni untuk berbagi studi kasus proyek dengan adik tingkat?', 'diproses', 'Halo Jessica, terima kasih inisiatifnya! Kami sedang menyiapkan program mentoring alumni SI untuk semester depan.', '2026-10-14 11:30:00', '2026-10-15 08:50:00'),
(14, 19, 'Tampilan Filter Bahan Kajian di HP', 'Halo admin, saya mengisi lewat smartphone dan filter Bahan Kajian berjalan lancar, hanya ingin menanyakan batas akhir pengisian periode ini.', 'selesai', 'Halo Jonathan, periode evaluasi 2025/2026 Ganjil dibuka hingga akhir bulan ini. Terima kasih sudah berpartisipasi.', '2026-10-15 16:05:00', '2026-10-16 08:10:00'),
(15, 49, 'Kebutuhan Magang Bidang ERP & PPIC', 'PT Indofood CBP membuka 4 kuota magang semester depan untuk mahasiswa SI yang memahami proses bisnis manufaktur dan basis data.', 'diproses', 'Terima kasih informasinya! Info lowongan magang akan kami teruskan ke koordinator Kerja Praktek Prodi SI.', '2026-10-16 09:45:00', '2026-10-17 10:00:00'),
(16, 44, 'Bantuan Verifikasi Data Tracer Study', 'Halo admin, saya sudah melengkapi seluruh bagian evaluasi termasuk pertanyaan Tracer Study. Apakah perlu mengisi form lain dari CDC?', 'selesai', 'Halo Tania, untuk evaluasi kurikulum prodi sudah lengkap tercatat. Bila ada form tambahan dari CDC universitas akan diinfokan terpisah.', '2026-10-17 14:25:00', '2026-10-17 15:40:00'),
(17, 21, 'Usulan Penambahan Materi Git & DevOps', 'Apakah usulan penambahan topik baru cukup ditulis di kolom saran bagian Kompetensi Umum?', 'selesai', 'Benar Vincentius, seluruh saran di bagian Kompetensi Umum akan direkap dan dibahas dalam evaluasi kurikulum prodi.', '2026-10-18 10:00:00', '2026-10-18 11:15:00'),
